<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Course;use App\Models\Enrollment;use App\Models\Group;use App\Models\User;use Illuminate\Http\Request;
class GroupController extends Controller{public function index(){return view('admin.groups.index',['groups'=>Group::withCount('users')->with('curator')->orderBy('name')->paginate(30)]);}public function create(){return $this->form(new Group);}public function edit(Group $group){return $this->form($group);}private function form(Group $group){return view('admin.groups.form',['group'=>$group,'users'=>User::where('role','student')->orderBy('name')->get(),'curators'=>User::whereIn('role',['teacher','admin'])->orderBy('name')->get(),'courses'=>Course::orderBy('title')->get()]);}public function store(Request $r){$g=Group::create($this->data($r));$this->sync($g,$r);return redirect()->route('admin.groups.index')->with('success','Группа создана');}public function update(Request $r,Group $group){$group->update($this->data($r));$this->sync($group,$r);return back()->with('success','Группа обновлена');}public function destroy(Group $group){$group->delete();return back()->with('success','Группа удалена');}public function assignCourses(Request $r,Group $group){$ids=$r->validate(['course_ids'=>'required|array','course_ids.*'=>'exists:courses,id'])['course_ids'];$group->courses()->syncWithoutDetaching($ids);foreach($group->users as $u)foreach($ids as $courseId)Enrollment::firstOrCreate(['course_id'=>$courseId,'user_id'=>$u->id],['status'=>'active','enrolled_at'=>now()]);return back()->with('success','Дисциплины назначены группе');}private function data(Request $r){return $r->validate(['name'=>'required|max:255','code'=>'nullable|max:100','curator_id'=>'nullable|exists:users,id','is_active'=>'nullable|boolean'])+['is_active'=>$r->boolean('is_active')];}private function sync(Group $g,Request $r){$g->users()->sync($r->input('user_ids',[]));$g->courses()->sync($r->input('course_ids',[]));foreach($g->users as $u)foreach($g->courses as $c)Enrollment::firstOrCreate(['course_id'=>$c->id,'user_id'=>$u->id],['status'=>'active','enrolled_at'=>now()]);}}
